-- Self-referencing table(s): 'WI1_RSTD_BKGS_BY_QUARTER' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   R_BKGS_BY_QUARTER.FISCAL_YEAR_QUARTER_NUMBER_INT,
   CASE
      WHEN R_BKGS_BY_QUARTER.PRODUCT_KEY = -998
         THEN UNIFORM(1005000, 1006800, RANDOM()) * -1
      WHEN R_BKGS_BY_QUARTER.PRODUCT_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.PRODUCT_KEY
   END PRODUCT_KEY,
   CASE
      WHEN R_BKGS_BY_QUARTER.SALES_TERRITORY_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.SALES_TERRITORY_KEY
   END SALES_TERRITORY_KEY,
   R_BKGS_BY_QUARTER.SALES_REP_NUMBER AS SALES_REP_NUM,
   CASE
      WHEN R_BKGS_BY_QUARTER.BILL_TO_CUSTOMER_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.BILL_TO_CUSTOMER_KEY
   END BILL_TO_CUSTOMER_KEY,
   CASE
      WHEN R_BKGS_BY_QUARTER.SOLD_TO_CUSTOMER_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.SOLD_TO_CUSTOMER_KEY
   END SOLD_TO_CUSTOMER_KEY,
   CASE
      WHEN R_BKGS_BY_QUARTER.SHIP_TO_CUSTOMER_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.SHIP_TO_CUSTOMER_KEY
   END SHIP_TO_CUSTOMER_KEY,
   CASE
      WHEN R_BKGS_BY_QUARTER.END_CUSTOMER_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      WHEN R_BKGS_BY_QUARTER.END_CUSTOMER_KEY = -888
         THEN UNIFORM(1005000, 1006800, RANDOM()) * -1
      WHEN R_BKGS_BY_QUARTER.END_CUSTOMER_KEY = -777
         THEN UNIFORM(1010000, 1011800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.END_CUSTOMER_KEY
   END END_CUSTOMER_KEY,
   R_BKGS_BY_QUARTER.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
   CASE
      WHEN R_BKGS_BY_QUARTER.PARTNER_PARTY_SITE_KEY = -999
         THEN UNIFORM(1000000, 1003000, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.PARTNER_PARTY_SITE_KEY
   END PARTNER_PARTY_SITE_KEY,
   R_BKGS_BY_QUARTER.WIPS_ORIGINATOR_ID_INT,
   R_BKGS_BY_QUARTER.SALESREP_FLAG AS SALESREP_FLG,
   R_BKGS_BY_QUARTER.SERVICE_FLAG AS SERVICE_FLG,
   R_BKGS_BY_QUARTER.CHANNEL_BOOKING_FLAG AS CHANNEL_BOOKING_FLG,
   R_BKGS_BY_QUARTER.EXTENDED_HOLD_QUANTITY AS EXTENDED_HOLD_QTY,
   R_BKGS_BY_QUARTER.EXTENDED_QUANTITY AS EXTENDED_QTY,
   R_BKGS_BY_QUARTER.COMP_US_LIST_PRICE_AMOUNT AS COMP_US_LIST_PRICE_AMT,
   R_BKGS_BY_QUARTER.COMP_US_HOLD_LIST_PRICE_AMT,
   R_BKGS_BY_QUARTER.COMP_US_HOLD_NET_PRICE_AMT,
   R_BKGS_BY_QUARTER.COMP_US_HOLD_COST_AMOUNT AS COMP_US_HOLD_COST_AMT,
   R_BKGS_BY_QUARTER.COMP_US_NET_PRICE_AMOUNT AS COMP_US_NET_PRICE_AMT,
   R_BKGS_BY_QUARTER.COMP_US_COST_AMOUNT AS COMP_US_COST_AMT,
   R_BKGS_BY_QUARTER.COMP_US_STANDARD_PRICE_AMT,
   R_BKGS_BY_QUARTER.TRADE_IN_AMOUNT AS TRADE_IN_AMT,
   R_BKGS_BY_QUARTER.CHANNEL_DROP_SHIP_FLG,
   R_BKGS_BY_QUARTER.CANCEL_CODE AS CANCEL_CD,
   R_BKGS_BY_QUARTER.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   /*Modified part of TRUE DEMAND */
   R_BKGS_BY_QUARTER.DV_CORPORATE_BOOKING_FLG AS CORPORATE_BOOKINGS_FLG,
   /*Added part of TRUE DEMAND */
   R_BKGS_BY_QUARTER.DV_REVENUE_RECOGNITION_FLG,
   /*Added part of TRUE DEMAND */
   R_BKGS_BY_QUARTER.DV_NET_SPREAD_FLG,
   R_BKGS_BY_QUARTER.DV_ATTRIBUTION_CD,
   CASE
      WHEN R_BKGS_BY_QUARTER.DV_PRODUCT_KEY = -998
         THEN UNIFORM(1005000, 1006800, RANDOM()) * -1
      WHEN R_BKGS_BY_QUARTER.DV_PRODUCT_KEY = -999
         THEN UNIFORM(1000000, 1001800, RANDOM()) * -1
      ELSE R_BKGS_BY_QUARTER.DV_PRODUCT_KEY
   END DV_PRODUCT_KEY,
   DV_FMV_FLG,
   /*FMV Q2FY15*/
   R_BKGS_BY_QUARTER.REVENUE_TRANSFER_KEY,
   /*Added as part of ICPM Q4fy15*/
   R_BKGS_BY_QUARTER.CALENDAR_YEAR_QUARTER_NUMBER_INT,
   /*ADDED ATTRIBUTE LOGIC AS PART OF DSV Q1FY16 BY */
   R_BKGS_BY_QUARTER.DSV_FLG,
   /*PNEELRAJ ADDED AS A PART OF ICPM Q3FY16 Feb CDR*/
   R_BKGS_BY_QUARTER.AS_OF_FSC_MTH_PTR_STE_PRTY_KEY,
   /*PNEELRAJ ADDED AS A PART OF ICPM Q3FY16 Feb CDR*/
   R_BKGS_BY_QUARTER.AS_OF_FSC_MTH_CHANNEL_BKGS_FLG,
   /* PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/
   R_BKGS_BY_QUARTER.DV_ROUTE_TO_MARKET_CD,
   /*ADDED THE BELOW COLUMNS AS PART OF RO PROJECT RELEASE: Q3FY17 */
   R_BKGS_BY_QUARTER.DV_AS_OF_FSC_MTH_RTM_CD /*PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/,
   R_BKGS_BY_QUARTER.XCAT_FLG,
   R_BKGS_BY_QUARTER.BK_OFFER_TYPE_NAME,
   R_BKGS_BY_QUARTER.RECURRING_OFFER_FLG,
   R_BKGS_BY_QUARTER.ELA_FLG,
   R_BKGS_BY_QUARTER.DV_PURCHASE_ADJ_DSCNT_USD_AMT /* Q1FY18 PA */,
   R_BKGS_BY_QUARTER.DV_RECURRING_OFFER_CD /*Q1FY18 RO */,
   R_BKGS_BY_QUARTER.DV_BKG_GROSS_MGN_AMOUNT /*added as part product BGM - Q1FY18 release */ AS DV_BKG_GROSS_MGN_AMT,
   R_BKGS_BY_QUARTER.DV_BGM_NON_STANDARD_COST_AMT /*added as part product BGM - Q1FY18 release */,
   R_BKGS_BY_QUARTER.POB_TYPE_CD,
   R_BKGS_BY_QUARTER.NRS_TRANSITION_FLG,
   R_BKGS_BY_QUARTER.SALES_MOTION_CD,
   R_BKGS_BY_QUARTER.SUMMARY_QUOTE_FLG,
   R_BKGS_BY_QUARTER.SALES_ADJUSTMENT_SOURCE_CODE AS SALES_ADJUSTMENT_SOURCE_CODE,
   R_BKGS_BY_QUARTER.BOOKING_CHANNEL_TYPE,
   R_BKGS_BY_QUARTER.BUNDLE_TYPE_CD /*ADDED AS PART OF NOAH SCOPE */
FROM
   {{ var('m_MT_RSTD_BKGS_BY_QUARTER_CORP_STGDB') }}.WI1_RSTD_BKGS_BY_QUARTER R_BKGS_BY_QUARTER